def length_of_longest_substring(s):
    last_index = {}
    left = 0
    best = 0
    for right, c in enumerate(s):
        if c in last_index and last_index[c] >= left:
            left = last_index[c] + 1
        last_index[c] = right
        cur = right - left + 1
        if cur > best:
            best = cur
    return best
